/**
 * Generate the client's Arabic goal map from the ONE authored source.
 *
 * `GOALS_AR` in `cloudflare-roleplay-anchors.js` is the only place a scenario's
 * learner-facing goal is written. The conversation header needs it before the
 * first turn (the server's reply carries it too, but a goal that appears only
 * after you speak is not a briefing), and the client cannot import worker code —
 * so this generated file is the bridge, and `tests/scenarioGoals.test.ts` fails
 * when it drifts from the source.
 *
 * Usage: node scripts/build-roleplay-goals.mjs [--check]
 */
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { GOALS_AR } from '../cloudflare-roleplay-anchors.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const target = join(root, 'src/lib/conversation/scenarioGoals.generated.ts');

const entries = Object.entries(GOALS_AR).sort(([a], [b]) => a.localeCompare(b));
const body = [
  '/**',
  ' * GENERATED by `node scripts/build-roleplay-goals.mjs` — do not edit by hand.',
  ' * Source: `GOALS_AR` in `cloudflare-roleplay-anchors.js`.',
  ' *',
  " * One Arabic sentence per served scenario id: the «مهمتك: …» line under the",
  ' * conversation title. Authored, never model-written.',
  ' */',
  'export const SCENARIO_GOALS_AR: Record<string, string> = {',
  ...entries.map(([id, goal]) => `  ${JSON.stringify(id)}: ${JSON.stringify(goal)},`),
  '};',
  '',
  '/** The authored goal for a scenario, or an empty string when it has none. */',
  'export function scenarioGoalAr(scenarioId: string | undefined | null): string {',
  '  if (!scenarioId) return \'\';',
  '  return SCENARIO_GOALS_AR[scenarioId] || \'\';',
  '}',
  '',
].join('\n');

if (process.argv.includes('--check')) {
  const current = await readFile(target, 'utf8').catch(() => '');
  if (current.replace(/\r\n/g, '\n') !== body) {
    console.error('scenarioGoals.generated.ts is stale — run node scripts/build-roleplay-goals.mjs');
    process.exit(1);
  }
  console.log(`scenario goals: ${entries.length} ids, up to date`);
} else {
  await writeFile(target, body, 'utf8');
  console.log(`scenario goals: ${entries.length} ids written`);
}
